let _markdown = "\n\nIntroduction [#introduction]\n\n<FeedbackBlock id=\"eeecd6e3f34bbb11\" body=\"MDX files will be compiled into JavaScript with exports like:\">\n  MDX files will be compiled into JavaScript with exports like:\n</FeedbackBlock>\n\n<FeedbackBlock id=\"1c8682f8bac27743\" body=\"default: the main component.frontmatter: frontmatter data.other properties generated by remark/rehype plugins.\">\n  * `default`: the main component.\n  * `frontmatter`: frontmatter data.\n  * other properties generated by remark/rehype plugins.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"c02ecec9d4a19cf4\" body=\"Hence, they can also be used as a page, or components that you can import.\">\n  Hence, they can also be used as a page, or components that you can import.\n</FeedbackBlock>\n\nUsing as Component [#using-as-component]\n\n<FeedbackBlock id=\"14789c9d38bb7d4b\" body=\"You can import them as a component:\">\n  You can import them as a component:\n</FeedbackBlock>\n\n```tsx title=\"app/my-page.tsx\"\nimport MyPage from '@/content/page.mdx';\nimport { getMDXComponents } from '@/mdx-components';\n\nexport default function Page() {\n  return (\n    <div className=\"prose\">\n      <MyPage components={getMDXComponents()} />\n    </div>\n  );\n}\n```\n\nUsing as Page [#using-as-page]\n\n<FeedbackBlock id=\"8137646ec7fde9ba\" body=\"On Next.js, you can use page.mdx instead of page.tsx for creating a new page under the app directory.\">\n  On Next.js, you can use `page.mdx` instead of `page.tsx` for creating a new page under the app directory.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"app/my-page/page.mdx\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"app/my-page/page.mdx\">\n      app/my-page/page.mdx\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"components/layouts/page.tsx\">\n      components/layouts/page.tsx\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"app/my-page/page.mdx\">\n    ```mdx\n    ---\n    title: My Page\n    ---\n\n    export { default } from '@/components/layouts/page';\n\n    # Hello World\n\n    This is my page.\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"components/layouts/page.tsx\">\n    ```tsx\n    import type { ComponentProps } from 'react';\n\n    export default function Content(props: ComponentProps<'main'>) {\n      return (\n        <main className=\"px-8 py-12\">\n          <article className=\"prose\">{props.children}</article>\n        </main>\n      );\n    }\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"3eafb6565c813968\" body=\"It doesn't have MDX components by default, you have to provide them:\">\n  It doesn't have **MDX components** by default, you have to provide them:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"mdx-components.tsx\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"mdx-components.tsx\">\n      mdx-components.tsx\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"source.config.ts\">\n      source.config.ts\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"mdx-components.tsx\">\n    ```tsx\n    import defaultMdxComponents from 'fumadocs-ui/mdx';\n    import type { MDXComponents } from 'mdx/types';\n\n    export function getMDXComponents(components?: MDXComponents): MDXComponents {\n      return {\n        ...defaultMdxComponents, // for Fumadocs UI\n        ...components,\n      };\n    }\n\n    // export a `useMDXComponents()` that returns MDX components\n    export const useMDXComponents = getMDXComponents; // [!code ++]\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"source.config.ts\">\n    ```ts\n    import { defineConfig } from 'fumadocs-mdx/config';\n\n    export default defineConfig({\n      mdxOptions: {\n        // Path to import your `mdx-components.tsx` above. [!code ++]\n        providerImportSource: '@/mdx-components',\n      },\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<Callout title=\"Other Frameworks?\">\n  Other React.js frameworks like Tanstack Start usually prefer explicit declaration of loaders, it's recommended to use them as components in your pages instead.\n</Callout>\n";
